/* eslint-disable prettier/prettier */
export const SHAPE_PREFIX = "GANTT_";
export const DATELINE_PREFIX = "GANTT_DATELINE_";

export async function clearGanttShapes(): Promise<void> {
  if (typeof Office === "undefined") return;
  await Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    sheet.load("shapes");
    await context.sync();
    const shapesCol = sheet.shapes;
    shapesCol.load("items/name");
    await context.sync();
    const shapes: Excel.Shape[] = shapesCol.items || [];
    let deleted = 0;
    for (let i = 0; i < shapes.length; i++) {
      const nm = shapes[i].name || "";
      if (nm.startsWith(SHAPE_PREFIX) || nm.startsWith(DATELINE_PREFIX)) {
        try {
          shapes[i].delete();
          deleted++;
        } catch {
          /* ignore */
        }
      }
    }
    if (deleted) await context.sync();
  });
}
