/* eslint-disable prettier/prettier */
import { BarStyle, BarStyleKey, GanttConfig } from "./types";
import { defaultBarStyles } from "./styles";
import { parseDateValue, normalizeBool, normalizeMilestone, normalizePercent } from "./dates";
import { buildAddress } from "./excelAddrs";
import { DATELINE_PREFIX, SHAPE_PREFIX } from "./shapes";

interface TaskRow {
  start?: Date;
  finish?: Date;
  baselineStart?: Date;
  baselineFinish?: Date;
  summary?: boolean;
  critical?: boolean;
  milestone?: boolean;
  percent?: number;
}

function validateConfig(cfg: GanttConfig) {
  if (!cfg) throw new Error("Config undefined");
  if (!cfg.colors) throw new Error("Config.colors missing");
  if (!cfg.barStyles) cfg.barStyles = { ...defaultBarStyles };
  else cfg.barStyles = { ...defaultBarStyles, ...cfg.barStyles };
}

export async function renderGantt(cfg: GanttConfig) {
  validateConfig(cfg);
  const rangePattern = /^(?:[^!]+!)?[A-Z]+\d+:[A-Z]+\d+$/;
  if (!cfg.ganttHeaderRange || !cfg.ganttHeaderRange.match(rangePattern)) {
    throw new Error("Missing or invalid ganttHeaderRange (e.g., A1:Z1)");
  }
  if (!cfg.startDatesRange || !cfg.finishDatesRange) throw new Error("Missing Start/Finish ranges");
  if (!cfg.startDatesRange.match(rangePattern) || !cfg.finishDatesRange.match(rangePattern)) {
    throw new Error("Invalid Start/Finish range formats");
  }

  if (typeof Office === "undefined") throw new Error("Office.js is not loaded");

  await Excel.run(async (context) => {
    try {
      context.application.suspendScreenUpdatingUntilNextSync();
      context.application.suspendApiCalculationUntilNextSync();
    } catch {}
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    sheet.load("name");
    await context.sync();

    const header = sheet.getRange(cfg.ganttHeaderRange!);
    header.load("values,columnCount,address,rowIndex,columnIndex");
    const startR = sheet.getRange(cfg.startDatesRange!);
    startR.load("rowCount,rowIndex,values,address");
    const finishR = sheet.getRange(cfg.finishDatesRange!);
    finishR.load("values");
    let baselineStartR: Excel.Range | null = null;
    if (cfg.baselineStartRange) {
      baselineStartR = sheet.getRange(cfg.baselineStartRange);
      baselineStartR.load("values");
    }
    let baselineFinishR: Excel.Range | null = null;
    if (cfg.baselineFinishRange) {
      baselineFinishR = sheet.getRange(cfg.baselineFinishRange);
      baselineFinishR.load("values");
    }
    let summaryR: Excel.Range | null = null;
    if (cfg.summaryRange) {
      summaryR = sheet.getRange(cfg.summaryRange);
      summaryR.load("values");
    }
    let criticalR: Excel.Range | null = null;
    if (cfg.criticalRange) {
      criticalR = sheet.getRange(cfg.criticalRange);
      criticalR.load("values");
    }
    let milestoneR: Excel.Range | null = null;
    if (cfg.milestoneRange) {
      milestoneR = sheet.getRange(cfg.milestoneRange);
      milestoneR.load("values");
    }
    let pctR: Excel.Range | null = null;
    if (cfg.percentCompleteRange) {
      pctR = sheet.getRange(cfg.percentCompleteRange);
      pctR.load("values");
    }

    await context.sync();

    const headerValues: any[][] = (header.values as any[][]) || [];
    const headerColumnCount: number = header.columnCount as any;
    const headerColIndex0: number = (header as any).columnIndex as number;
    const startValues: any[][] = (startR.values as any[][]) || [];
    const finishValues: any[][] = (finishR.values as any[][]) || [];
    const baselineStartValues: any[][] | undefined = baselineStartR
      ? ((baselineStartR as any).values as any[][])
      : undefined;
    const baselineFinishValues: any[][] | undefined = baselineFinishR
      ? ((baselineFinishR as any).values as any[][])
      : undefined;
    let summaryValues: any[][] | undefined;
    if (summaryR) summaryValues = (summaryR as any).values as any[][];
    let criticalValues: any[][] | undefined;
    if (criticalR) criticalValues = (criticalR as any).values as any[][];
    let milestoneValues: any[][] | undefined;
    if (milestoneR) milestoneValues = (milestoneR as any).values as any[][];
    let pctValues: any[][] | undefined;
    if (pctR) pctValues = (pctR as any).values as any[][];

    if (!headerValues?.[0]) throw new Error("No header data found");
    if (!startValues?.length) throw new Error("No start date data found");
    if (!finishValues?.length) throw new Error("No finish date data found");

    const currentSelection = context.workbook.getSelectedRange();
    currentSelection.load("address");
    await context.sync();
    const savedSelectionAddress: string = currentSelection.address;

    const headerDates: Date[] = [];
    for (let c = 0; c < headerColumnCount; c++) {
      const v = headerValues[0][c];
      const d = parseDateValue(v);
      headerDates.push(d || new Date("Invalid"));
    }

    // Remove existing shapes (optionally scoped by row filter)
    const rowFilterDel: Set<number> | undefined =
      (cfg as any)._rowFilter instanceof Set ? (cfg as any)._rowFilter : undefined;
    sheet.load("shapes");
    await context.sync();
    const shapesCol = sheet.shapes;
    shapesCol.load("items/name");
    await context.sync();
    const shapeObjs: Excel.Shape[] = shapesCol.items || [];
    let deletedAny = false;
    for (let i = 0; i < shapeObjs.length; i++) {
      const nm = shapeObjs[i].name || "";
      if (nm.startsWith(SHAPE_PREFIX)) {
        if (rowFilterDel) {
          const parts = nm.split("_");
          const rowStr = parts[2];
          const r = parseInt(rowStr, 10);
          if (!rowFilterDel.has(r)) continue;
        }
        try {
          shapeObjs[i].delete();
          deletedAny = true;
        } catch {}
        continue;
      }
      if (nm.startsWith(DATELINE_PREFIX)) {
        try {
          shapeObjs[i].delete();
          deletedAny = true;
        } catch {}
      }
    }
    if (deletedAny) await context.sync();

    // Validate header dates
    const validDates = headerDates.filter((d) => !isNaN(d.getTime()));
    if (!validDates.length) throw new Error("No valid dates found in the Gantt header row");

    const rowCount = startValues.length;
    const tasks: TaskRow[] = [];
    const rowFilter: Set<number> | undefined =
      (cfg as any)._rowFilter instanceof Set ? (cfg as any)._rowFilter : undefined;
    for (let r = 0; r < rowCount; r++) {
      if (rowFilter && !rowFilter.has(r)) {
        tasks.push({});
        continue;
      }
      const task: TaskRow = {};
      const sDate = parseDateValue(startValues[r]?.[0]);
      const fDate = parseDateValue(finishValues[r]?.[0]);
      if (sDate && !isNaN(sDate.getTime()) && sDate.getFullYear() > 1900) task.start = sDate;
      if (fDate && !isNaN(fDate.getTime()) && fDate.getFullYear() > 1900) task.finish = fDate;
      if (baselineStartValues) {
        const bd = parseDateValue(baselineStartValues[r]?.[0]);
        if (bd) task.baselineStart = bd;
      }
      if (baselineFinishValues) {
        const bd = parseDateValue(baselineFinishValues[r]?.[0]);
        if (bd) task.baselineFinish = bd;
      }
      if (summaryValues) task.summary = normalizeBool(summaryValues[r]?.[0]);
      if (criticalValues) task.critical = normalizeBool(criticalValues[r]?.[0]);
      if (milestoneValues) task.milestone = normalizeMilestone(milestoneValues[r]?.[0]);
      if (pctValues) task.percent = normalizePercent(pctValues[r]?.[0]);
      tasks.push(task);
    }

    // Positions
    const body = startR;
    let firstBodyRow = startR.getCell(0, 0);
    firstBodyRow.load("top");
    let rowHeights: number[] = [];
    const rowObjects: Excel.Range[] = [];
    for (let r = 0; r < rowCount; r++) {
      const row = body.getRow(r);
      row.format.load("rowHeight");
      rowObjects.push(row);
      rowHeights.push(15);
    }
    const colWidths: number[] = [];
    const colObjects: Excel.Range[] = [];
    for (let c = 0; c < headerColumnCount; c++) {
      const cell = header.getCell(0, c);
      cell.format.load("columnWidth");
      cell.load("left");
      colObjects.push(cell);
      colWidths.push(8);
    }
    await context.sync();
    for (let r = 0; r < rowCount; r++) {
      const h = rowObjects[r].format.rowHeight;
      rowHeights[r] = typeof h === "number" && h > 0 ? h : 25;
    }
    for (let c = 0; c < headerColumnCount; c++) {
      const w = colObjects[c].format.columnWidth;
      colWidths[c] = typeof w === "number" && w > 0 ? w : 50;
    }
    const ganttRangeLeft = (colObjects[0] as any)?.left || 0;
    const ganttRangeTop = (firstBodyRow as any)?.top || 0;

    const columnLefts: number[] = headerDates.map((_, idx) => {
      const headerCell: any = colObjects[idx];
      if (headerCell && typeof headerCell.left === "number") return headerCell.left;
      return ganttRangeLeft + colWidths.slice(0, idx).reduce((s, w) => s + w, 0);
    });
    const columnRights: number[] = columnLefts.map((l, idx) => l + (colWidths[idx] || 0));

    let dataDate: Date | undefined;
    if (cfg.dataDateRange) {
      const maybeIso = String(cfg.dataDateRange).trim();
      if (/^\d{4}-\d{2}-\d{2}$/.test(maybeIso)) {
        const parsed = parseDateValue(maybeIso);
        if (parsed) dataDate = parsed;
      } else {
        try {
          const ddR = sheet.getRange(maybeIso);
          ddR.load("values");
          await context.sync();
          const parsed = parseDateValue(((ddR.values as any[][]) || [])[0]?.[0]);
          if (parsed) dataDate = parsed;
        } catch {}
      }
    }

    function dateToPixel(d?: Date): number | undefined {
      if (!d || isNaN(d.getTime())) return undefined;
      const first = headerDates[0];
      const lastIdx = headerDates.length - 1;
      const last = headerDates[lastIdx];
      if (d.getTime() <= first.getTime()) return columnLefts[0];
      if (d.getTime() >= last.getTime()) return columnRights[lastIdx];
      for (let i = 0; i < headerDates.length - 1; i++) {
        const a = headerDates[i];
        const b = headerDates[i + 1];
        if (isNaN(a.getTime()) || isNaN(b.getTime())) continue;
        if (d.getTime() >= a.getTime() && d.getTime() < b.getTime()) {
          const span = b.getTime() - a.getTime();
          const ratio = span > 0 ? (d.getTime() - a.getTime()) / span : 0;
          const left = columnLefts[i];
          const width = colWidths[i] || 0;
          return left + ratio * width;
        }
      }
      return columnRights[lastIdx];
    }

    function findColumn(dates: Date[], d?: Date | null): number {
      if (!d || isNaN(d.getTime())) return -1;
      const n = dates.length;
      if (!n) return -1;
      if (d.getTime() < dates[0].getTime()) return -1;
      if (d.getTime() >= dates[n - 1].getTime()) return n - 1;
      for (let i = 0; i < n - 1; i++) {
        const a = dates[i];
        const b = dates[i + 1];
        if (isNaN(a.getTime()) || isNaN(b.getTime())) continue;
        if (d.getTime() >= a.getTime() && d.getTime() < b.getTime()) return i;
      }
      return -1;
    }

    interface ShapePlan {
      type: "baseline" | "bar" | "progress" | "milestone";
      rowIdx: number;
      startCol: number;
      endCol: number;
      color: string;
      percent?: number;
      startDate?: Date;
      finishDate?: Date;
      styleKey?: BarStyleKey;
      milestoneShape?: boolean;
    }
    const plans: ShapePlan[] = [];
    const rowFilter2: Set<number> | undefined =
      (cfg as any)._rowFilter instanceof Set ? (cfg as any)._rowFilter : undefined;
    tasks.forEach((t, idx) => {
      if (rowFilter2 && !rowFilter2.has(idx)) return;
      if (t && t.milestone) {
        if (t.start && !t.finish) t.finish = t.start;
        else if (!t.start && t.finish) t.start = t.finish;
        if (t.baselineStart && !t.baselineFinish) t.baselineFinish = t.baselineStart;
        else if (!t.baselineStart && t.baselineFinish) t.baselineStart = t.baselineFinish;
      }
      if (!t.start || !t.finish || t.finish < t.start) return;
      let startCol = findColumn(headerDates, t.start);
      let endCol = findColumn(headerDates, t.finish);
      if (startCol === -1 && t.start < headerDates[0]) startCol = 0;
      if (endCol === -1 && t.finish > headerDates[headerDates.length - 1])
        endCol = headerDates.length - 1;
      if (startCol === -1 && t.start > headerDates[headerDates.length - 1]) return;
      if (endCol === -1 && t.finish < headerDates[0]) return;
      if (startCol === -1 || endCol === -1) return;
      const isMilestoneShape = !!t.milestone;
      const actualStateKey: BarStyleKey = t.summary
        ? "summary"
        : t.critical
          ? "critical"
          : "normal";
      if (isMilestoneShape) {
        plans.push({
          type: "milestone",
          rowIdx: idx,
          startCol,
          endCol: startCol,
          color: (cfg.barStyles || defaultBarStyles)[actualStateKey].color,
          startDate: t.start,
          styleKey: actualStateKey,
          milestoneShape: true,
        });
      } else {
        plans.push({
          type: "bar",
          rowIdx: idx,
          startCol,
          endCol,
          color: (cfg.barStyles || defaultBarStyles)[actualStateKey].color,
          startDate: t.start,
          finishDate: t.finish,
          styleKey: actualStateKey,
          milestoneShape: false,
        });
      }
      if (t.baselineStart && t.baselineFinish) {
        let bStartCol = findColumn(headerDates, t.baselineStart);
        let bEndCol = findColumn(headerDates, t.baselineFinish);
        if (bStartCol === -1 && t.baselineStart < headerDates[0]) bStartCol = 0;
        if (bEndCol === -1 && t.baselineFinish > headerDates[headerDates.length - 1])
          bEndCol = headerDates.length - 1;
        if (isMilestoneShape) {
          if (bStartCol > -1)
            plans.push({
              type: "baseline",
              rowIdx: idx,
              startCol: bStartCol,
              endCol: bStartCol,
              color: cfg.colors.baseline,
              startDate: t.baselineStart,
              styleKey: "baseline",
              milestoneShape: true,
            });
        } else if (bStartCol > -1 && bEndCol > -1)
          plans.push({
            type: "baseline",
            rowIdx: idx,
            startCol: bStartCol,
            endCol: bEndCol,
            color: cfg.colors.baseline,
            startDate: t.baselineStart,
            finishDate: t.baselineFinish,
            styleKey: "baseline",
            milestoneShape: false,
          });
      }
      if (!isMilestoneShape && t.percent != null && t.percent > 0) {
        const percentEnd = new Date(
          t.start.getTime() + (t.finish.getTime() - t.start.getTime()) * t.percent
        );
        const pEndCol = findColumn(headerDates, percentEnd);
        if (pEndCol > -1)
          plans.push({
            type: "progress",
            rowIdx: idx,
            startCol,
            endCol: pEndCol,
            color: (cfg.barStyles || defaultBarStyles).progress.color,
            percent: t.percent,
            styleKey: "progress",
            startDate: t.start,
            finishDate: t.finish,
            milestoneShape: false,
          });
      }
    });

    rowHeights = rowHeightsOrDefault(rowHeights, rowCount);
    function rowHeightsOrDefault(rh: number[], count: number) {
      return rh.length === count ? rh : new Array(count).fill(20);
    }

    function dateToDimensions(
      start?: Date,
      finish?: Date,
      percent?: number
    ): { left: number; width: number } {
      let leftPx = start ? dateToPixel(start)! : (undefined as any);
      let rightPx = finish ? dateToPixel(finish)! : (undefined as any);
      if (percent != null && start && finish) {
        const dur = finish.getTime() - start.getTime();
        const prog = new Date(start.getTime() + dur * percent);
        rightPx = dateToPixel(prog)!;
      }
      if (leftPx == null) leftPx = columnLefts[0];
      if (rightPx == null) rightPx = leftPx + Math.max(6, colWidths[0] || 20);
      if (rightPx < leftPx) {
        const t = leftPx;
        leftPx = rightPx;
        rightPx = t;
      }
      return { left: leftPx, width: Math.max(3, rightPx - leftPx) };
    }

    let successfulShapes = 0;
    for (let i = 0; i < plans.length; i++) {
      const p = plans[i];
      try {
        const styles = cfg.barStyles || defaultBarStyles;
        const barStyle = p.styleKey ? styles[p.styleKey] : undefined;
        const geometryStyle: BarStyle = p.type === "baseline" ? styles.baseline : styles.normal;
        const wantsRadius = !!(geometryStyle && geometryStyle.radiusPct > 0.001);
        const isMilestoneDiamond = !!p.milestoneShape;
        const geomType = isMilestoneDiamond
          ? (Excel.GeometricShapeType as any).diamond || Excel.GeometricShapeType.rectangle
          : wantsRadius
            ? Excel.GeometricShapeType.roundRectangle
            : Excel.GeometricShapeType.rectangle;
        const shape = shapesCol.addGeometricShape(geomType as any);
        shape.name = `${SHAPE_PREFIX}${p.type}_${p.rowIdx}_${i}`;
        // Vertical position
        let topBase = ganttRangeTop;
        for (let r = 0; r < p.rowIdx; r++) topBase += rowHeights[r] || 20;
        const actualRowHeightPx = rowHeights[p.rowIdx] || 20;
        let barHeightPx = Math.max(2, actualRowHeightPx * (geometryStyle.heightPct ?? 1));
        let topOffsetExtra = actualRowHeightPx * (geometryStyle.topOffsetPct ?? 0);
        shape.top = topBase + topOffsetExtra;
        // Horizontal
        const dims =
          p.type === "progress"
            ? dateToDimensions(p.startDate, p.finishDate, p.percent)
            : dateToDimensions(p.startDate, p.finishDate);
        if (isMilestoneDiamond) {
          const size = Math.max(6, barHeightPx);
          shape.width = size;
          shape.left = dims.left - size / 2;
          shape.height = size;
        } else {
          shape.left = dims.left;
          shape.width = dims.width;
          shape.height = barHeightPx;
        }
        // Color/border
        shape.fill.setSolidColor(barStyle ? barStyle.color : p.color);
        if (barStyle && barStyle.borderEnabled) {
          try {
            shape.lineFormat.visible = true;
            if (barStyle.borderColor) shape.lineFormat.color = barStyle.borderColor;
            if (barStyle.borderWidthPx != null) shape.lineFormat.weight = barStyle.borderWidthPx;
          } catch {}
        } else {
          try {
            shape.lineFormat.visible = false;
          } catch {}
        }
        // Radius
        if (wantsRadius && !isMilestoneDiamond) {
          try {
            const adj = (shape as any).adjustments;
            if (adj && typeof adj.getItem === "function") {
              const a0 = adj.getItem(0);
              if (a0) {
                const raw = Math.min(1, Math.max(0, geometryStyle.radiusPct));
                a0.value = raw;
                if (raw > 0.5) {
                  try {
                    a0.value = raw / 2;
                  } catch {}
                }
              }
            }
          } catch {}
        }
        successfulShapes++;
      } catch {}
    }

    // Data date vertical line
    if (dataDate) {
      try {
        const x = dateToPixel(dataDate);
        if (typeof x === "number") {
          const lineShape = shapesCol.addGeometricShape(Excel.GeometricShapeType.rectangle as any);
          lineShape.name = `${DATELINE_PREFIX}${dataDate.toISOString()}`;
          const lineWidth = Math.max(1, Math.min(12, (cfg.dataDateWidthPx ?? 2) | 0));
          lineShape.left = x - Math.floor(lineWidth / 2);
          const totalHeight = rowHeights.reduce((s, h) => s + h, 0) || rowCount * 20;
          lineShape.top = ganttRangeTop;
          lineShape.width = lineWidth;
          lineShape.height = totalHeight;
          lineShape.fill.setSolidColor(cfg.dataDateColor || "#FF0000");
          try {
            lineShape.lineFormat.visible = false;
          } catch {}
        }
      } catch {}
    }

    try {
      if (savedSelectionAddress) sheet.getRange(savedSelectionAddress).select();
    } catch {}
    await context.sync();
  });
}
