/* eslint-disable prettier/prettier */
export function colIndexToLetter(idx: number): string {
  let n = idx + 1;
  let s = "";
  while (n > 0) {
    const rem = (n - 1) % 26;
    s = String.fromCharCode(65 + rem) + s;
    n = Math.floor((n - 1) / 26);
  }
  return s;
}

export function buildAddress(
  sheetName: string,
  row1: number,
  col1: number,
  row2: number,
  col2: number
) {
  const a = `${colIndexToLetter(col1 - 1)}${row1}`;
  const b = `${colIndexToLetter(col2 - 1)}${row2}`;
  return `${sheetName}!${a}:${b}`;
}

export function parseAddressRowSpan(address: string): { startRow: number; endRow: number } | null {
  const excl = address.split("!").pop() || address;
  const parts = excl.split(":");
  const parseOne = (ref: string): number | null => {
    const m = ref.match(/([A-Z]+)(\d+)/i);
    if (!m) return null;
    return parseInt(m[2], 10);
  };
  const r1 = parseOne(parts[0]);
  const r2 = parts[1] ? parseOne(parts[1]) : r1;
  if (r1 == null || r2 == null) return null;
  return { startRow: Math.min(r1, r2), endRow: Math.max(r1, r2) };
}
