/* eslint-disable prettier/prettier */
import { GanttConfig } from "./types";
import { buildAddress } from "./excelAddrs";
import { parseDateValue } from "./dates";

function textAt(values: any[][], r: number, c: number): string {
  const v = values[r]?.[c];
  return typeof v === "string" ? v.trim() : "";
}

export async function detectRangesSmart(): Promise<Partial<GanttConfig>> {
  return Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    const used = sheet.getUsedRange();
    sheet.load("name");
    used.load("values,rowCount,columnCount,address,rowIndex,columnIndex");
    await context.sync();
    const sheetAddr: string = used.address || "";
    const sheetName = sheetAddr.includes("!") ? sheetAddr.split("!")[0] : sheet.name;
    const top = (used as any).rowIndex as number;
    const left = (used as any).columnIndex as number;
    const rowCount = used.rowCount as number;
    const colCount = used.columnCount as number;
    const values = (used.values as any[][]) || [];
    const maxRows = Math.min(rowCount, 600);
    const maxCols = Math.min(colCount, 120);
    const sliceVals: any[][] = [];
    for (let r = 0; r < maxRows; r++) sliceVals.push(values[r]?.slice(0, maxCols) ?? []);

    // Find header row with longest increasing date run
    let headerRow: number | null = null;
    let headerStart: number | null = null;
    let headerEnd: number | null = null;
    for (let r = 0; r < Math.min(8, maxRows); r++) {
      let runStart = -1;
      let last: Date | null = null;
      let bestLen = 0;
      let bestStart = -1;
      let bestEnd = -1;
      for (let c = 0; c < maxCols; c++) {
        const d = parseDateValue(sliceVals[r]?.[c]);
        const ok = !!(d && !isNaN(d.getTime())) && (!last || d!.getTime() > last!.getTime());
        if (ok) {
          if (runStart < 0) runStart = c;
          last = d!;
        } else {
          if (runStart >= 0) {
            const len = c - runStart;
            if (len > bestLen) {
              bestLen = len;
              bestStart = runStart;
              bestEnd = c - 1;
            }
          }
          runStart = -1;
          last = null;
        }
      }
      if (runStart >= 0) {
        const len = maxCols - runStart;
        if (len > bestLen) {
          bestLen = len;
          bestStart = runStart;
          bestEnd = maxCols - 1;
        }
      }
      if (bestLen >= 3) {
        headerRow = r;
        headerStart = bestStart;
        headerEnd = bestEnd;
        break;
      }
    }

    const out: Partial<GanttConfig> = {};
    if (headerRow != null) {
      out.ganttHeaderRange = buildAddress(
        sheetName,
        top + headerRow + 1,
        left + headerStart! + 1,
        top + headerRow + 1,
        left + headerEnd! + 1
      );
    }

    const bodyStartLocal = headerRow != null ? headerRow + 1 : 1;

    // Use header/label text to identify columns
    const norm = (s: string) =>
      s
        .toLowerCase()
        .replace(/[^a-z0-9%]+/g, " ")
        .trim()
        .replace(/\s+/g, " ");
    const colHeaderTexts: Record<number, string[]> = {};
    for (let r = 0; r < Math.min(8, maxRows); r++) {
      for (let c = 0; c < maxCols; c++) {
        const t = textAt(sliceVals, r, c).toLowerCase();
        if (!t) continue;
        const key = left + c;
        colHeaderTexts[key] = colHeaderTexts[key] || [];
        if (!colHeaderTexts[key].includes(t)) colHeaderTexts[key].push(t);
      }
    }
    const includesAll = (tokSet: Set<string>, toks: string[]) => toks.every((t) => tokSet.has(t));
    const anyMatch = (arr: string[], groups: string[][], exclude?: string[]) => {
      for (const h of arr) {
        const T = norm(h).split(" ").filter(Boolean);
        const set = new Set(T);
        if (exclude && exclude.some((e) => set.has(e))) continue;
        for (const g of groups) if (includesAll(set, g)) return true;
      }
      return false;
    };
    const findColsBySynonyms = (groups: string[][], exclude?: string[]) => {
      const cols: number[] = [];
      for (const [k, arr] of Object.entries(colHeaderTexts))
        if (anyMatch(arr, groups, exclude)) cols.push(Number(k));
      return cols.sort((a, b) => a - b);
    };

    const startSyn = [
      ["start"],
      ["early", "start"],
      ["planned", "start"],
      ["activity", "start"],
      ["task", "start"],
      ["es"],
    ];
    const finishSyn = [
      ["finish"],
      ["end"],
      ["late", "finish"],
      ["planned", "finish"],
      ["activity", "finish"],
      ["task", "finish"],
      ["ef"],
      ["lf"],
    ];
    const excludeBLAct = ["baseline", "bl", "actual"];
    const startCol = findColsBySynonyms(startSyn, excludeBLAct)[0];
    const finishCol = findColsBySynonyms(finishSyn, excludeBLAct)[0];

    function scoreDateCol(absCol: number): number {
      const localCol = absCol - left;
      let cnt = 0;
      for (let r = bodyStartLocal; r < maxRows; r++) {
        const d = parseDateValue(sliceVals[r]?.[localCol]);
        if (d && !isNaN(d.getTime())) cnt++;
      }
      return cnt;
    }
    let sCol = startCol;
    let fCol = finishCol;
    if (sCol == null || fCol == null) {
      // fallback: pick top 2 date-rich columns
      const scores: { col: number; score: number }[] = [];
      for (let c = 0; c < maxCols; c++)
        scores.push({ col: left + c, score: scoreDateCol(left + c) });
      scores.sort((a, b) => b.score - a.score);
      if (scores[0]) sCol = scores[0].col;
      if (scores[1]) fCol = scores[1].col;
    }

    // Compute common row span across detected columns
    const candidateCols = [sCol, fCol].filter((x) => typeof x === "number") as number[];
    let firstLocal = Number.MAX_SAFE_INTEGER;
    let lastLocal = -1;
    for (const abs of candidateCols) {
      const local = abs - left;
      for (let r = bodyStartLocal; r < maxRows; r++) {
        const v = sliceVals[r]?.[local];
        if (v !== undefined && v !== null && `${v}`.trim() !== "") {
          if (firstLocal === Number.MAX_SAFE_INTEGER) firstLocal = r;
          lastLocal = r;
        }
      }
    }
    if (!(lastLocal >= firstLocal && firstLocal !== Number.MAX_SAFE_INTEGER)) {
      firstLocal = bodyStartLocal;
      lastLocal = bodyStartLocal;
    }
    const r1 = top + firstLocal + 1;
    const r2 = top + lastLocal + 1;
    if (typeof sCol === "number")
      out.startDatesRange = buildAddress(sheetName, r1, sCol + 1, r2, sCol + 1);
    if (typeof fCol === "number")
      out.finishDatesRange = buildAddress(sheetName, r1, fCol + 1, r2, fCol + 1);

    if (headerRow != null) {
      out.ganttBodyRange = buildAddress(
        sheetName,
        r1,
        left + headerStart! + 1,
        r2,
        left + headerEnd! + 1
      );
    }

    return out;
  });
}
