/* eslint-disable prettier/prettier */
import { GanttConfig } from "./types";
import { parseAddressRowSpan } from "./excelAddrs";
import { renderGantt } from "./gantt";

const AUTO_UPDATE_DEBOUNCE_MS = 300;
let eventHandler: any | null = null;
let autoUpdateTimer: any | null = null;

async function rerenderRows(cfg: GanttConfig, taskRowIdxs: number[]) {
  if (!taskRowIdxs.length) return;
  await renderGantt({ ...cfg, _rowFilter: new Set(taskRowIdxs) } as any);
}

export async function enableAutoUpdate(
  cfg: GanttConfig,
  callback: (rows?: number[]) => Promise<void> | void
) {
  await Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    if (eventHandler) {
      try {
        eventHandler.remove();
      } catch {
        /* ignore */
      }
      eventHandler = null;
    }
    eventHandler = sheet.onChanged.add(async (e: any) => {
      if (autoUpdateTimer) clearTimeout(autoUpdateTimer);
      autoUpdateTimer = setTimeout(async () => {
        try {
          const addr: string | undefined = e?.address;
          if (!addr) {
            await callback();
            return;
          }
          let bodyStartRow: number | null = null;
          if (cfg.ganttBodyRange) {
            const span = parseAddressRowSpan(cfg.ganttBodyRange);
            if (span) bodyStartRow = span.startRow;
          } else if (cfg.ganttHeaderRange && cfg.startDatesRange) {
            const span = parseAddressRowSpan(cfg.startDatesRange);
            if (span) bodyStartRow = span.startRow;
          }
          const changedSpan = parseAddressRowSpan(addr);
          if (!bodyStartRow || !changedSpan) {
            await callback();
            return;
          }
          const taskRowIdxs: number[] = [];
          for (let r = changedSpan.startRow; r <= changedSpan.endRow; r++) {
            const idx = r - bodyStartRow;
            if (idx >= 0) taskRowIdxs.push(idx);
          }
          if (!taskRowIdxs.length) return;
          const uniq = Array.from(new Set(taskRowIdxs));
          await rerenderRows(cfg, uniq);
          await Promise.resolve(callback(uniq));
        } catch (err) {
          try {
            await renderGantt(cfg);
            await Promise.resolve(callback());
          } catch {
            /* swallow */
          }
        }
      }, AUTO_UPDATE_DEBOUNCE_MS);
    });
    await context.sync();
  });
}

export function disableAutoUpdate() {
  if (eventHandler) {
    eventHandler.remove();
    eventHandler = null;
  }
}
