/* eslint-disable prettier/prettier */
import { GanttConfig } from "./types";

const STORAGE_KEY = "ganttConfigV1";
const SETTINGS_PREFIX = "ExTimelineConfig:";

function safeParseJSON<T = any>(v: unknown): T | undefined {
  if (v == null) return undefined;
  if (typeof v === "object") return v as T;
  if (typeof v === "string") {
    try {
      return JSON.parse(v) as T;
    } catch {
      return undefined;
    }
  }
  return undefined;
}

export function loadPersistedConfig(): Partial<GanttConfig> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

export function persistConfig(cfg: GanttConfig) {
  try {
    const { _rowFilter, ...clean } = cfg as any;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(clean));
  } catch {
    /* ignore */
  }
}

export async function loadSheetScopedConfig(): Promise<Partial<GanttConfig>> {
  try {
    return await Excel.run(async (context) => {
      const sheet = context.workbook.worksheets.getActiveWorksheet();
      sheet.load("name");
      await context.sync();
      const sheetName = sheet.name;
      const settings = context.workbook.settings;
      const key = SETTINGS_PREFIX + sheetName;
      const item = settings.getItemOrNullObject(key);
      item.load("isNullObject,value");
      await context.sync();
      if (!item.isNullObject && item.value != null) {
        const parsed = safeParseJSON<GanttConfig>(item.value as any);
        if (parsed) return parsed;
      }
      return {};
    });
  } catch {
    return loadPersistedConfig();
  }
}

export async function persistSheetScopedConfig(cfg: GanttConfig): Promise<void> {
  try {
    await Excel.run(async (context) => {
      const sheet = context.workbook.worksheets.getActiveWorksheet();
      sheet.load("name");
      await context.sync();
      const sheetName = sheet.name;
      const key = SETTINGS_PREFIX + sheetName;
      const settings = context.workbook.settings;
      const existing = settings.getItemOrNullObject(key);
      existing.load("isNullObject");
      await context.sync();
      if (!existing.isNullObject) existing.value = cfg;
      else settings.add(key, cfg);
      persistConfig(cfg);
      await context.sync();
    });
  } catch {
    persistConfig(cfg);
  }
}
