/* eslint-disable prettier/prettier */
export function cleanPrimaveraDateAnnotations(s: string): string {
  if (!s) return s as any;
  let t = s.trim();
  t = t.replace(/[\sA*]+$/i, "").trim();
  return t;
}

function excelSerialToDate(n: number): Date {
  return new Date((n - 25569) * 86400 * 1000);
}

export function parseDateValue(raw: any): Date | null {
  if (raw == null || raw === "") return null;
  try {
    if (raw instanceof Date) return isNaN(raw.getTime()) ? null : raw;
    if (typeof raw === "number") return excelSerialToDate(raw);
    if (typeof raw === "string") {
      const cleaned = cleanPrimaveraDateAnnotations(raw);
      if (!cleaned) return null;
      const numPattern = /^\d+(?:\.\d+)?$/;
      if (numPattern.test(cleaned)) {
        const num = parseFloat(cleaned);
        if (!isNaN(num)) return excelSerialToDate(num);
      }
      const d = new Date(cleaned);
      if (!isNaN(d.getTime()) && d.getFullYear() > 1900) return d;
      return null;
    }
    const d = new Date(raw);
    return isNaN(d.getTime()) ? null : d;
  } catch {
    return null;
  }
}

export function normalizeBool(v: any): boolean {
  if (v == null) return false;
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  if (typeof v === "string") {
    const s = v.trim().toLowerCase();
    if (s === "") return false;
    if (["true", "t", "yes", "y", "1"].includes(s)) return true;
    if (["false", "f", "no", "n", "0"].includes(s)) return false;
    const num = Number(s);
    if (!isNaN(num)) return num !== 0;
    return false;
  }
  return false;
}

export function normalizePercent(v: any): number | undefined {
  if (v == null || v === "") return undefined;
  const n = typeof v === "number" ? v : parseFloat(v);
  if (isNaN(n)) return undefined;
  return n > 1 ? n / 100 : n;
}

export function normalizeMilestone(v: any): boolean {
  if (v == null) return false;
  if (typeof v === "string") {
    const s = v.trim().toLowerCase();
    if (!s) return false;
    if (s.includes("milestone")) return true;
    return normalizeBool(s);
  }
  return normalizeBool(v);
}
